class Solution {
public:
    int largestUniqueNumber(vector<int>& nums) {
        unordered_map<int, int> freq;
        for (int x : nums) {
            ++freq[x];
        }
        int answer = -1;
        for (const auto& item : freq) {
            if (item.second == 1) {
                answer = max(answer, item.first);
            }
        }
        return answer;
    }
};
